export enum ErrorCodeEnum {
  VALIDATION = 'BAD_REQUEST.VALIDATION',
  IDEMPOTENCY_KEY_INVALID = 'BAD_REQUEST.IDEMPOTENCY_KEY',
  ROOM_NOT_FOUND = 'NOT_FOUND.ROOM',
  BOOKING_NOT_FOUND = 'NOT_FOUND.BOOKING',
  IDEMPOTENCY_IN_PROGRESS = 'CONFLICT.IDEMPOTENCY_IN_PROGRESS',
  IDEMPOTENCY_KEY_REUSED = 'UNPROCESSABLE.IDEMPOTENCY_KEY_REUSED',
  SERVICE_UNAVAILABLE = 'UNAVAILABLE.SERVICE',
}
import { BookingDto } from '@roombook/contract';

export enum ClaimBookingOutcomeEnum {
  CREATED = 'CREATED',
  REPLAYED = 'REPLAYED',
  KEY_REUSED = 'KEY_REUSED',
  IN_PROGRESS = 'IN_PROGRESS',
}

export class ClaimBookingResultDto {
  outcome: ClaimBookingOutcomeEnum;
  booking: BookingDto | null;
}
import { HttpStatus, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
import { CreateBookingDto } from '@roombook/contract';
import { DataSource, EntityManager, Repository } from 'typeorm';
import { toBookingDto } from './booking.mapper';
import { ClaimBookingOutcomeEnum, ClaimBookingResultDto } from './claim-booking-result.dto';

type TryLockRow = { locked: boolean };

const TRY_LOCK_SQL = 'SELECT pg_try_advisory_xact_lock(hashtextextended($1, 0)) AS "locked"';

@Injectable()
export class IdempotentBookingRepository {
  constructor(
    @InjectRepository(IdempotencyKeyEntity) private readonly idempotencyKeys: Repository<IdempotencyKeyEntity>,
    private readonly dataSource: DataSource,
  ) {}

  findByKey(key: string): Promise<IdempotencyKeyEntity | null> {
    return this.idempotencyKeys.findOneBy({ key });
  }

  async claim(key: string, fingerprint: string, booking: CreateBookingDto): Promise<ClaimBookingResultDto> {
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();
    await queryRunner.startTransaction();
    try {
      const result = await this.claimWithin(queryRunner.manager, key, fingerprint, booking);
      await queryRunner.commitTransaction();
      return result;
    } catch (error) {
      await queryRunner.rollbackTransaction();
      throw error;
    } finally {
      await queryRunner.release();
    }
  }

  private async claimWithin(
    manager: EntityManager,
    key: string,
    fingerprint: string,
    booking: CreateBookingDto,
  ): Promise<ClaimBookingResultDto> {
    if (!(await this.tryLock(manager, `${key}:${fingerprint}`))) {
      return { outcome: ClaimBookingOutcomeEnum.IN_PROGRESS, booking: null };
    }
    if (!(await this.tryLock(manager, key))) {
      return { outcome: ClaimBookingOutcomeEnum.KEY_REUSED, booking: null };
    }
    const stored = await manager.findOneBy(IdempotencyKeyEntity, { key });
    if (stored) {
      return stored.requestFingerprint === fingerprint
        ? { outcome: ClaimBookingOutcomeEnum.REPLAYED, booking: stored.responseBody }
        : { outcome: ClaimBookingOutcomeEnum.KEY_REUSED, booking: null };
    }
    return this.insertBookingWithKey(manager, key, fingerprint, booking);
  }

  private async tryLock(manager: EntityManager, lockName: string): Promise<boolean> {
    const [row]: TryLockRow[] = await manager.query(TRY_LOCK_SQL, [lockName]);
    return row.locked;
  }

  private async insertBookingWithKey(
    manager: EntityManager,
    key: string,
    fingerprint: string,
    booking: CreateBookingDto,
  ): Promise<ClaimBookingResultDto> {
    const saved = await manager.save(BookingEntity, {
      roomId: booking.roomId,
      title: booking.title,
      organizerEmail: booking.organizerEmail,
      startsAt: new Date(booking.startsAt),
      endsAt: new Date(booking.endsAt),
    });
    const responseBody = toBookingDto(saved);
    await manager.insert(IdempotencyKeyEntity, {
      key,
      requestFingerprint: fingerprint,
      responseStatus: HttpStatus.CREATED,
      responseBody,
    });
    return { outcome: ClaimBookingOutcomeEnum.CREATED, booking: responseBody };
  }
}
import { Injectable } from '@nestjs/common';
import { ExceptionHelper } from '@roombook/backend-common';
import { CreateBookingDto, CreateBookingMessageDto, CreateBookingResultDto, ErrorCodeEnum } from '@roombook/contract';
import { bookingFingerprint } from './booking-fingerprint.util';
import { isEndAfterStart, parseBookingInstant } from './booking-time-range.util';
import { ClaimBookingOutcomeEnum, ClaimBookingResultDto } from './claim-booking-result.dto';
import { ConfirmationQueueProducer } from './confirmation-queue.producer';
import { IdempotentBookingRepository } from './idempotent-booking.repository';
import { RoomClient } from './room.client';

@Injectable()
export class CreateBookingService {
  constructor(
    private readonly roomClient: RoomClient,
    private readonly idempotentBookingRepository: IdempotentBookingRepository,
    private readonly confirmationQueueProducer: ConfirmationQueueProducer,
  ) {}

  async createBooking(message: CreateBookingMessageDto): Promise<CreateBookingResultDto> {
    const key = message.idempotencyKey.toLowerCase();
    const fingerprint = bookingFingerprint(message.booking);
    const stored = await this.idempotentBookingRepository.findByKey(key);
    if (stored) {
      return stored.requestFingerprint === fingerprint
        ? { booking: stored.responseBody, replayed: true }
        : this.raiseKeyReused();
    }
    this.assertTimeRange(message.booking);
    await this.roomClient.findRoomById(message.booking.roomId);
    const claim = await this.idempotentBookingRepository.claim(key, fingerprint, message.booking);
    const result = this.toResult(claim);
    if (claim.outcome === ClaimBookingOutcomeEnum.CREATED) {
      await this.confirmationQueueProducer.enqueue(result.booking.id);
    }
    return result;
  }

  private toResult(claim: ClaimBookingResultDto): CreateBookingResultDto {
    if (claim.outcome === ClaimBookingOutcomeEnum.IN_PROGRESS) {
      ExceptionHelper.conflict(
        ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS,
        'A request with this Idempotency-Key is still being processed',
      );
    }
    const booking = claim.booking ?? this.raiseKeyReused();
    return { booking, replayed: claim.outcome === ClaimBookingOutcomeEnum.REPLAYED };
  }

  private raiseKeyReused(): never {
    return ExceptionHelper.unprocessable(
      ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED,
      'Idempotency-Key was already used with a different request body',
    );
  }

  private assertTimeRange(booking: CreateBookingDto): void {
    const startsAt = parseBookingInstant(booking.startsAt);
    const endsAt = parseBookingInstant(booking.endsAt);
    if (!startsAt || !endsAt) {
      ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'startsAt and endsAt must be valid date-times');
    }
    if (!isEndAfterStart(startsAt, endsAt)) {
      ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'endsAt must be later than startsAt');
    }
  }
}
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { BookingEntity } from '@roombook/backend-common';
import {
  ConfirmationStatusEnum,
  ListBookingsQueryDto,
  RecordConfirmationResultDto,
  UpdateBookingDto,
} from '@roombook/contract';
import { LessThanOrEqual, Repository } from 'typeorm';

type ReturnedBookingRows = [BookingEntity[], number];

const RETURNING_BOOKING = `RETURNING
  "id",
  "room_id" AS "roomId",
  "title",
  "organizer_email" AS "organizerEmail",
  "starts_at" AS "startsAt",
  "ends_at" AS "endsAt",
  "confirmation_status" AS "confirmationStatus",
  "confirmation_attempts" AS "confirmationAttempts",
  "created_at" AS "createdAt",
  "updated_at" AS "updatedAt"`;

const toInstantOrNull = (value: string | undefined): Date | null => (value === undefined ? null : new Date(value));

@Injectable()
export class BookingRepository {
  constructor(@InjectRepository(BookingEntity) private readonly bookings: Repository<BookingEntity>) {}

  findPage(query: ListBookingsQueryDto): Promise<[BookingEntity[], number]> {
    return this.bookings.findAndCount({
      where: query.roomId ? { roomId: query.roomId } : {},
      order: { startsAt: 'ASC', id: 'ASC' },
      skip: (query.page - 1) * query.limit,
      take: query.limit,
    });
  }

  findById(id: string): Promise<BookingEntity | null> {
    return this.bookings.findOneBy({ id });
  }

  async updateIfTimeRangeValid(id: string, changes: UpdateBookingDto): Promise<BookingEntity | null> {
    const [rows]: ReturnedBookingRows = await this.bookings.query(
      `UPDATE "bookings"
      SET
        "title" = COALESCE($2::varchar, "title"),
        "starts_at" = COALESCE($3::timestamptz, "starts_at"),
        "ends_at" = COALESCE($4::timestamptz, "ends_at"),
        "updated_at" = now()
      WHERE "id" = $1
        AND COALESCE($4::timestamptz, "ends_at") > COALESCE($3::timestamptz, "starts_at")
      ${RETURNING_BOOKING}`,
      [id, changes.title ?? null, toInstantOrNull(changes.startsAt), toInstantOrNull(changes.endsAt)],
    );
    return rows[0] ?? null;
  }

  async deleteById(id: string): Promise<BookingEntity | null> {
    const [rows]: ReturnedBookingRows = await this.bookings.query(
      `DELETE FROM "bookings" WHERE "id" = $1 ${RETURNING_BOOKING}`,
      [id],
    );
    return rows[0] ?? null;
  }

  async recordConfirmationResult(report: RecordConfirmationResultDto): Promise<BookingEntity | null> {
    await this.bookings.update(
      {
        id: report.bookingId,
        confirmationStatus: ConfirmationStatusEnum.PENDING,
        confirmationAttempts: LessThanOrEqual(report.attempts),
      },
      { confirmationStatus: report.status, confirmationAttempts: report.attempts, updatedAt: () => 'now()' },
    );
    return this.bookings.findOneBy({ id: report.bookingId });
  }
}
import { Injectable } from '@nestjs/common';
import { ExceptionHelper } from '@roombook/backend-common';
import {
  BookingDto,
  ErrorCodeEnum,
  ListBookingsQueryDto,
  PagedBookingsDto,
  RecordConfirmationResultDto,
  UpdateBookingDto,
  UpdateBookingMessageDto,
} from '@roombook/contract';
import { parseBookingInstant } from './booking-time-range.util';
import { toBookingDto } from './booking.mapper';
import { BookingRepository } from './booking.repository';

const hasNoChange = (changes: UpdateBookingDto): boolean =>
  changes.title === undefined && changes.startsAt === undefined && changes.endsAt === undefined;

const isInstantOrAbsent = (value: string | undefined): boolean =>
  value === undefined || parseBookingInstant(value) !== null;

@Injectable()
export class BookingService {
  constructor(private readonly bookingRepository: BookingRepository) {}

  async listBookings(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
    const [entities, total] = await this.bookingRepository.findPage(query);
    return { items: entities.map(toBookingDto), total, page: query.page, limit: query.limit };
  }

  async findBookingById(id: string): Promise<BookingDto> {
    const entity = await this.bookingRepository.findById(id);
    return entity ? toBookingDto(entity) : ExceptionHelper.notFound(ErrorCodeEnum.BOOKING_NOT_FOUND, 'Booking not found');
  }

  async updateBooking(message: UpdateBookingMessageDto): Promise<BookingDto> {
    const { id, changes } = message;
    if (hasNoChange(changes)) {
      return this.findBookingById(id);
    }
    if (!isInstantOrAbsent(changes.startsAt) || !isInstantOrAbsent(changes.endsAt)) {
      ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'startsAt and endsAt must be valid date-times');
    }
    const updated = await this.bookingRepository.updateIfTimeRangeValid(id, changes);
    if (updated) {
      return toBookingDto(updated);
    }
    await this.findBookingById(id);
    return ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'endsAt must be later than startsAt');
  }

  async deleteBooking(id: string): Promise<BookingDto> {
    const deleted = await this.bookingRepository.deleteById(id);
    return deleted ? toBookingDto(deleted) : ExceptionHelper.notFound(ErrorCodeEnum.BOOKING_NOT_FOUND, 'Booking not found');
  }

  async recordConfirmationResult(report: RecordConfirmationResultDto): Promise<BookingDto | null> {
    const stored = await this.bookingRepository.recordConfirmationResult(report);
    return stored ? toBookingDto(stored) : null;
  }
}
export const parseBookingInstant = (value: string): Date | null => {
  const instant = new Date(value);
  return Number.isNaN(instant.getTime()) ? null : instant;
};

export const isEndAfterStart = (startsAt: Date, endsAt: Date): boolean => endsAt.getTime() > startsAt.getTime();

