describe('BookingRepository', () => {
  let repository: BookingRepository;
  let findAndCount: jest.Mock;
  let findOneBy: jest.Mock;
  let query: jest.Mock;
  let update: jest.Mock;

  beforeEach(async () => {
    findAndCount = jest.fn().mockResolvedValue([[bookingEntity()], 1]);
    findOneBy = jest.fn();
    query = jest.fn();
    update = jest.fn().mockResolvedValue({ affected: 1 });
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingRepository,
        { provide: getRepositoryToken(BookingEntity), useValue: { findAndCount, findOneBy, query, update } },
      ],
    }).compile();
    repository = moduleRef.get(BookingRepository);
  });

  describe('findPage', () => {
    it('orders by start then id and pages with the requested limit', async () => {
      await expect(repository.findPage({ page: 3, limit: 5 })).resolves.toEqual([[bookingEntity()], 1]);

      expect(findAndCount).toHaveBeenCalledWith({
        where: {},
        order: { startsAt: 'ASC', id: 'ASC' },
        skip: 10,
        take: 5,
      });
    });

    it('restricts rows and total to the room when a roomId is given', async () => {
      await repository.findPage({ page: 1, limit: 10, roomId: ROOM_ID });

      expect(findAndCount).toHaveBeenCalledWith({
        where: { roomId: ROOM_ID },
        order: { startsAt: 'ASC', id: 'ASC' },
        skip: 0,
        take: 10,
      });
    });
  });

  describe('findById', () => {
    it('returns the booking', async () => {
      const entity = bookingEntity();
      findOneBy.mockResolvedValue(entity);

      await expect(repository.findById(BOOKING_ID)).resolves.toBe(entity);
      expect(findOneBy).toHaveBeenCalledWith({ id: BOOKING_ID });
    });

    it('returns null for an unknown booking', async () => {
      findOneBy.mockResolvedValue(null);

      await expect(repository.findById(BOOKING_ID)).resolves.toBeNull();
    });
  });

  describe('updateIfTimeRangeValid', () => {
    it('applies only the sent fields in one conditional update that sets updated_at', async () => {
      const entity = bookingEntity();
      query.mockResolvedValue([[entity], 1]);

      await expect(
        repository.updateIfTimeRangeValid(BOOKING_ID, { endsAt: '2030-01-07T11:00:00.000Z' }),
      ).resolves.toBe(entity);

      expect(query).toHaveBeenCalledTimes(1);
      const [sql, parameters] = query.mock.calls[0];
      expect(sql).toMatch(/^UPDATE "bookings"/);
      expect(sql).toContain('"title" = COALESCE($2::varchar, "title")');
      expect(sql).toContain('"starts_at" = COALESCE($3::timestamptz, "starts_at")');
      expect(sql).toContain('"ends_at" = COALESCE($4::timestamptz, "ends_at")');
      expect(sql).toContain('"updated_at" = now()');
      expect(sql).toContain('COALESCE($4::timestamptz, "ends_at") > COALESCE($3::timestamptz, "starts_at")');
      expect(sql).toContain('RETURNING');
      expect(parameters).toEqual([BOOKING_ID, null, null, new Date('2030-01-07T11:00:00.000Z')]);
    });

    it('passes every sent field', async () => {
      query.mockResolvedValue([[bookingEntity()], 1]);

      await repository.updateIfTimeRangeValid(BOOKING_ID, {
        title: 'Planning',
        startsAt: '2030-01-07T08:00:00.000Z',
        endsAt: '2030-01-07T08:30:00.000Z',
      });

      expect(query.mock.calls[0][1]).toEqual([
        BOOKING_ID,
        'Planning',
        new Date('2030-01-07T08:00:00.000Z'),
        new Date('2030-01-07T08:30:00.000Z'),
      ]);
    });

    it('returns null when no row matched', async () => {
      query.mockResolvedValue([[], 0]);

      await expect(repository.updateIfTimeRangeValid(BOOKING_ID, { title: 'Planning' })).resolves.toBeNull();
    });
  });

