        setTime(label, '2030-01-07T11:00');
      } else {
        await user.type(control, 'x');
        await user.keyboard('{Backspace}');
      }
      await submit(user);

      await waitFor(() => expect(mockedCreateBooking).toHaveBeenCalledTimes(2));
      expect(keyOfCall(1)).not.toBe(keyOfCall(0));
    },
  );
});

